  'node.generate-image.f5': 'Ratio',
  'node.browseract.f1': 'Tableau de bord BrowserAct → votre bot → son identifiant. Le test de la clé (Réglages › Clés API) liste les bots du compte.',
  'node.browseract.f2': 'Une paire « nom = valeur » par ligne, avec les noms définis par le bot (ex. « url = https://… »).',
