  'node.browseract.f4': 'Un bot navigue réellement le site : compter des minutes, pas des secondes.',
  'node.compare-catalog.f1': 'Mêmes domaines que la moisson. IGNORÉ si un node « Sites sources » est branché sur le port sites.',
  'node.compare-catalog.f2': 'fourni par « Sites sources »',
  'node.compare-catalog.f3': 'fourni par « Sites sources »',
