  'node.harvest-competitor.f1': 'Domaine par ligne. Ex : « pro-motoculture.com ». PrestaShop supporté nativement. IGNORÉ si un node « Sites sources » est branché sur le port sites.',
  'node.harvest-competitor.f2': 'fourni par « Sites sources »',
  'node.harvest-competitor.f3': 'Laisse VIDE si tu branches ta feuille source sur le port « products » : les familles sont alors lues dans la colonne ci-dessous, toujours à jour. Remplis-le pour FORCER un ciblage précis (« COURROIES, FILTRATION »). Vide et sans feuille = catalogue complet.',
  'node.harvest-competitor.f4': 'Ex : Famille. Utilisée quand la feuille source est branchée : les familles distinctes en sont extraites, puis une IA apparie VOTRE vocabulaire à celui du concurrent (« COURROIES » retrouve son rayon « transmission »). Sans IA disponible, le catalogue complet est balayé — jamais moins.',
  'node.harvest-competitor.f5': 'Laisse VIDE : le suivi est automatiquement celui du workflow (partagé avec « Comparer catalogue » du même workflow). Ne remplis que pour partager un même suivi entre plusieurs workflows.',
  'node.harvest-competitor.f6': 'fourni par « Sites sources »',
  'node.list-products.f1': 'URLs de pages liste (ou DOMAINES si « Famille » est renseigné)',
  'node.list-products.f2': 'Une par ligne. Soit des URLs de page liste, soit — si tu remplis « Famille produit » — juste des domaines (ex : castorama.fr, leroymerlin.fr).',
  'node.list-products.f3': 'Famille produit (découverte auto)',
  'node.list-products.f4': 'Max produits (total)',
  'node.list-products.f5': '0 = pas de limite. Plafond sur le total agrégé (toutes URLs + pages).',
  'node.list-products.f6': 'Pages à parcourir par URL',
  'node.list-products.f7': 'Pagination : 1 = page seule ; N = suit aussi les pages 2..N (catalogues paginés).',
  'node.list-products.f8': 'Param de pagination',
  'node.list-products.f9': 'Nom du paramètre d’URL de page. Ex : « page » (défaut), « p » (Leroy Merlin).',
  'node.list-products.f10': 'Enrichir chaque fiche (EAN, marque, prix)',
  'node.list-products.f11': 'Va chercher sur CHAQUE fiche produit l’EAN/marque/prix canoniques (JSON-LD, cascade Jina→Firecrawl→Bright Data). Plus complet mais 1 requête par produit (plus lent).',
  'node.list-products.f12': 'Marque (filtre)',
  'node.list-products.f13': 'Si renseigné (ex « Ryobi »), ne garde que les produits dont la marque ou le nom contient ce terme — écarte le bruit (ex robots Sunseeker dans une recherche « tondeuse ryobi »). Vide = aucun filtrage.',
  'node.if-else.f1': 'Condition',
  'node.if-else.f2': 'Expression JS qui retourne un booléen. Utilise `value` pour la valeur d\'entrée. Ex : value > 10, value === \'ok\', value?.length > 0',
  'node.pipe.f1': 'Expressions (1 par ligne)',
  'node.pipe.f2': 'Chaque ligne = une expression JS appliquée séquentiellement. Utilise `value` pour la valeur courante. Ex :\\nvalue.rows\\nvalue.filter(r => r.active)\\nvalue.length',
