  'pw.kpi.index': 'Indice tarif',
  'pw.kpi.index.sub': 'base 100 = médiane marché',
  'pw.kpi.index.title': 'Indice TARIF base 100 : votre prix rapporté au prix médian des concurrents appariés, médiane sur tout le catalogue.\n100 = vous êtes au niveau du marché · 105 = 5 % au-dessus · 95 = 5 % en dessous.\n\nCalculé sur le catalogue COMPLET (pas sur l’échantillon borné) : contrairement à l’écart médian, il ne dérive pas quand le rapport est tronqué.\n\nVos prix source étant des tarifs NON REMISÉS, c’est un indice de positionnement catalogue — pas un indice net client.',
  'pw.kpi.index.stale': 'Rapport antérieur à cet indicateur : valeur recalculée sur l’échantillon borné. Relance une analyse pour l’indice exact.',
  'pw.kpi.gap': 'Écart unitaire cumulé',
  'pw.kpi.gap.sub': 'Σ à l’unité · {median} méd.',
  'pw.kpi.gap.title': 'Somme, sur les produits sous-cotés, de l’écart UNITAIRE entre votre prix et le meilleur prix concurrent.\n\n⚠ Ce n’est PAS un montant de chiffre d’affaires : sans volume de ventes, 3 € sur une pièce vendue 4 fois par an pèsent autant que 3 € sur une pièce vendue 8 000 fois. À lire comme une mesure d’ampleur, pas d’impact.\n\nSous-titre : écart médian sur les paires produit × concurrent',
