  'tst.ss.credsRequired': 'Email et mot de passe requis.',
  'tst.mv.specsComparedDesc': '{count} spec(s) fabricant comparées',
  'tst.svg.classifying': 'Classification logos / éditorial…',
  'tst.svg.rereadingPrices': 'Relecture de {count} prix…',
  'tst.svg.semanticAnalysis': 'Analyse sémantique (Gemini 3.5)…',
